    static int[] dfs(int node) {
        if (tree[node].isEmpty()) {
            // leaf
            return new int[]{1, 1};
        }

        List<int[]> childResults = new ArrayList<>();
        for (int child : tree[node]) {
            childResults.add(dfs(child));
        }

        int m = childResults.size();
        int minEval = 0, maxEval = 0;

        if (vals[node] == 1) {
            // MAX node: choose child with max value
            // For min evaluations: we want to find the child with minimal leaf count
            // among those that can produce the max value.
            // For max evaluations: we may have to check all children in worst case.
            int bestMin = Integer.MAX_VALUE;
            int bestMax = 0;
            // Find the minimal possible min evaluation among children that can give max value
            // Since all children are symmetric in value (just -1 times child's value),
            // the max value node will always pick the child with highest value.
            // But here all children are equivalent in terms of value structure,
            // so we need to consider the min/max leaf count strategy.

            // For min evaluations: we can order children so that the first child that gives
            // the max value is evaluated early. That child should have smallest leaf count.
            int minChildMin = Integer.MAX_VALUE;
            int maxChildMax = 0;
            for (int[] res : childResults) {
                minChildMin = Math.min(minChildMin, res[0]);
                maxChildMax = Math.max(maxChildMax, res[1]);
            }
            // Min evaluations: we can pick the child with smallest min leaf count first
            bestMin = minChildMin;
            // Max evaluations: in worst case, we evaluate all children until the last one gives max
            // So sum of all child max leaf counts except possibly one?
            // Actually worst case: the max-valued child is last, so we evaluate all children fully.
            // Sum of max leaf counts of all children
            int sumMax = 0;
            for (int[] res : childResults) {
                sumMax += res[1];
            }
            bestMax = sumMax;
            return new int[]{bestMin, bestMax};
        } else {
            // MIN node: choose child with min value
            // For min evaluations: we can order children so that the child with smallest
            // leaf count that gives min value is first.
            int minChildMin = Integer.MAX_VALUE;
            int maxChildMax = 0;
