                minChildMin = Math.min(minChildMin, res[0]);
                maxChildMax = Math.max(maxChildMax, res[1]);
            }
            // Min evaluations: pick child with smallest min leaf count
            int bestMin = minChildMin;
            // Max evaluations: worst case, evaluate all children
            int sumMax = 0;
            for (int[] res : childResults) {
                sumMax += res[1];
            }
            int bestMax = sumMax;
            return new int[]{bestMin, bestMax};
