            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            children[u].add(v);
        }
        minE = new long[n]; maxE = new long[n];
        dfs(0);
        System.out.println(minE[0] + " " + maxE[0]);
    }

    static void dfs(int u) {
        if (children[u].isEmpty()) { minE[u] = maxE[u] = 1; return; }
        for (int c : children[u]) dfs(c);
        long sumMax = 0, minMin = Long.MAX_VALUE;
        for (int c : children[u]) { sumMax += maxE[c]; minMin = Math.min(minMin, minE[c]); }
        maxE[u] = sumMax;
        minE[u] = minMin + (children[u].size() - 1);
    }
}

