public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int n;
    static int[] val;
    static ArrayList<Integer>[] children;
    static int[] leaves;
    static int[] mn;
    static int[] mx;

    static void dfs(int v) {
        if (children[v].isEmpty()) {
            leaves[v] = 1;
            mn[v] = 1;
            mx[v] = 1;
            return;
        }

        int totalLeaves = 0;
        for (int to : children[v]) {
            dfs(to);
            totalLeaves += leaves[to];
        }
        leaves[v] = totalLeaves;

        if (val[v] == 1) {
            // max node in original minimax, equivalent to OR:
            // minimum leaves needed = choose best child first
            int bestMn = Integer.MAX_VALUE;
            int sumMx = 0;
            for (int to : children[v]) {
                bestMn = Math.min(bestMn, mn[to]);
                sumMx += mx[to];
            }
            mn[v] = bestMn;
            mx[v] = sumMx;
        } else {
            // min node in original minimax, equivalent to AND:
            // minimum leaves needed = need all children
            // maximum leaves needed = can stop at worst child after others fully checked
            int sumMn = 0;
            int bestMx = 0;
            for (int to : children[v]) {
                sumMn += mn[to];
                bestMx = Math.max(bestMx, mx[to]);
            }
            mn[v] = sumMn;
            mx[v] = bestMx;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        n = fs.nextInt();

        val = new int[n + 1];
        for (int i = 1; i <= n; i++) val[i] = fs.nextInt();

        children = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) children[i] = new ArrayList<>();

        for (int i = 2; i <= n; i++) {
            int p = fs.nextInt();
            children[p].add(i);
        }

        leaves = new int[n + 1];
        mn = new int[n + 1];
        mx = new int[n + 1];

        dfs(1);

        int totalLeaves = leaves[1];
        int minEvaluations = totalLeaves - mx[1] + 1;
        int maxEvaluations = totalLeaves - mn[1] + 1;

        System.out.println(minEvaluations + " " + maxEvaluations);
    }
}

