#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int *a;
    int sz, cap;
} Vec;

void vec_push(Vec *v, int x) {
    if (v->sz == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->a = (int*)realloc(v->a, v->cap * sizeof(int));
    }
    v->a[v->sz++] = x;
}

int cmp_ll(const void *p1, const void *p2) {
    ll a = *(const ll*)p1;
    ll b = *(const ll*)p2;
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

int cmp_ll_desc(const void *p1, const void *p2) {
    ll a = *(const ll*)p1;
    ll b = *(const ll*)p2;
    if (a > b) return -1;
    if (a < b) return 1;
    return 0;
}

int n;
ll *val;
Vec *ch;
ll *mnv, *mxv;
ll *mnc, *mxc;

void dfs(int v) {
    if (ch[v].sz == 0) {
        mnv[v] = mxv[v] = val[v];
        mnc[v] = mxc[v] = 1;
        return;
    }

    int k = ch[v].sz;
    ll *child_mnv = (ll*)malloc(k * sizeof(ll));
    ll *child_mxv = (ll*)malloc(k * sizeof(ll));

    for (int i = 0; i < k; ++i) {
        int u = ch[v].a[i];
        dfs(u);
        child_mnv[i] = mnv[u];
        child_mxv[i] = mxv[u];
    }

    ll bestMin = -(1LL << 60);
    ll bestMax = -(1LL << 60);
    for (int i = 0; i < k; ++i) {
        ll candMin = -mxv[ch[v].a[i]];
        ll candMax = -mnv[ch[v].a[i]];
        if (candMin > bestMin) bestMin = candMin;
        if (candMax > bestMax) bestMax = candMax;
    }
    mnv[v] = bestMin;
    mxv[v] = bestMax;

    ll need = -mnv[v];
    ll ansMin = (1LL << 60);

    for (int i = 0; i < k; ++i) {
        int u = ch[v].a[i];
        ll first = mnc[u];
        ll extra = 0;
        for (int j = 0; j < k; ++j) if (j != i) {
            int w = ch[v].a[j];
            if (mnv[w] <= need && need <= mxv[w]) extra += mnv[w] == mxv[w] ? 0 : 0;
        }
        (void)first;
    }

    ll *fixed = (ll*)malloc(k * sizeof(ll));
    int fsz = 0;
    ll *cand = (ll*)malloc(k * sizeof(ll));
    int csz = 0;

    for (int i = 0; i < k; ++i) {
        int u = ch[v].a[i];
        if (mxv[u] < need) {
            fixed[fsz++] = mxc[u];
        } else if (mnv[u] >= need) {
            fixed[fsz++] = mnc[u];
        } else {
            cand[csz++] = mnc[u];
        }
    }

    qsort(fixed, fsz, sizeof(ll), cmp_ll);
    ll sum = 0;
    for (int i = 0; i < fsz; ++i) sum += fixed[i];
    ansMin = sum;
    if (csz > 0) {
        ll best = (1LL << 60);
        for (int i = 0; i < csz; ++i) {
            if (cand[i] < best) best = cand[i];
        }
        ansMin += best;
    }
    mnc[v] = ansMin;

    ll need2 = -mxv[v];
    fsz = csz = 0;
    for (int i = 0; i < k; ++i) {
        int u = ch[v].a[i];
        if (mxv[u] < need2) {
            fixed[fsz++] = mxc[u];
        } else if (mnv[u] >= need2) {
            fixed[fsz++] = mnc[u];
        } else {
            cand[csz++] = mxc[u];
        }
    }
    qsort(fixed, fsz, sizeof(ll), cmp_ll_desc);
    sum = 0;
    for (int i = 0; i < fsz; ++i) sum += fixed[i];
    ll ansMax = sum;
    if (csz > 0) {
        ll best = 0;
        for (int i = 0; i < csz; ++i) {
            if (cand[i] > best) best = cand[i];
        }
        ansMax += best;
    }
    mxc[v] = ansMax;

    free(child_mnv);
    free(child_mxv);
    free(fixed);
    free(cand);
}

int main() {
    if (scanf("%d", &n) != 1) return 0;

    val = (ll*)malloc((n + 1) * sizeof(ll));
    ch = (Vec*)calloc(n + 1, sizeof(Vec));
    mnv = (ll*)malloc((n + 1) * sizeof(ll));
    mxv = (ll*)malloc((n + 1) * sizeof(ll));
    mnc = (ll*)malloc((n + 1) * sizeof(ll));
    mxc = (ll*)malloc((n + 1) * sizeof(ll));

    for (int i = 1; i <= n; ++i) scanf("%lld", &val[i]);

    for (int i = 2; i <= n; ++i) {
        int p;
        scanf("%d", &p);
        vec_push(&ch[p], i);
    }

    dfs(1);
    printf("%lld %lld\n", mnc[1], mxc[1]);

    for (int i = 1; i <= n; ++i) free(ch[i].a);
    free(val);
    free(ch);
    free(mnv);
    free(mxv);
    free(mnc);
    free(mxc);
    return 0;
}

