using ll = long long;

int n;
vector<int> val;
vector<vector<int>> g;

pair<ll,ll> dfs(int v) {
    if (g[v].empty()) {
        return {1, 1}; // one leaf, must evaluate it
    }

    vector<pair<ll,ll>> child;
    ll sumLeaves = 0;
    ll minLeaves = (ll)4e18;

    for (int to : g[v]) {
        auto res = dfs(to);
        child.push_back(res);
        minLeaves = min(minLeaves, res.first);
        sumLeaves += res.second;
    }

    if (val[v] == 1) {
        // OR node: min can follow best child, max needs all
        return {minLeaves, sumLeaves};
    } else {
        // AND node: min needs all, max can follow worst child
        ll sumMin = 0;
        ll maxMax = 0;
        for (auto &p : child) {
            sumMin += p.first;
            maxMax = max(maxMax, p.second);
        }
        return {sumMin, maxMax};
    }
}

